import{_ as e,C as d,o as i,c as l,j as a,a as s,E as p,a3 as r}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"断占总诀篇之三：观物占","description":"以卦象观察器物的形、色、数与成败，深化以象断物的训练。","frontmatter":{"title":"断占总诀篇之三：观物占","description":"以卦象观察器物的形、色、数与成败，深化以象断物的训练。","category":"学习计划 · 第三阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/duan-zhan-zong-jue/observing-things-divination.md","filePath":"yijing/meihua-yishu/duan-zhan-zong-jue/observing-things-divination.md","lastUpdated":1787738987000}'),o={name:"yijing/meihua-yishu/duan-zhan-zong-jue/observing-things-divination.md"};function h(c,t,g,b,u,m){const n=d("DaoTextReading");return i(),l("div",null,[t[0]||(t[0]=a("h1",{id:"【断占总诀篇之三】诸卦反对性情·占物类例·物数为体诀·观物诸诀·万物戏验",tabindex:"-1"},[s("【断占总诀篇之三】诸卦反对性情·占物类例·物数为体诀·观物诸诀·万物戏验 "),a("a",{class:"header-anchor",href:"#【断占总诀篇之三】诸卦反对性情·占物类例·物数为体诀·观物诸诀·万物戏验","aria-label":'Permalink to "【断占总诀篇之三】诸卦反对性情·占物类例·物数为体诀·观物诸诀·万物戏验"'},"​")],-1)),t[1]||(t[1]=a("blockquote",null,[a("p",null,"本篇专论「观物占」——通过卦象断定手中或笼中之物的性质、形色、数目、成败。是梅花易数「以象断物」最完整的专论。")],-1)),t[2]||(t[2]=a("hr",null,null,-1)),t[3]||(t[3]=a("h2",{id:"📜-原文",tabindex:"-1"},[s("📜 原文 "),a("a",{class:"header-anchor",href:"#📜-原文","aria-label":'Permalink to "📜 原文"'},"​")],-1)),p(n,{colophon:"诸卦反对 · 占物类例 · 万物戏验",tone:"ink",sections:[{id:"sec-1-1",label:"诸卦反对性情",showLabel:!0,sentences:[["干刚坤柔反其义，",{text:"比卦",glossary:"g02"},"欢欣困忧虑。"]]},{id:"sec-1-2",label:"",showLabel:!0,sentences:[["临逢百物观求之，",{text:"蒙卦",glossary:"g04"},"难明屯不失。"]]},{id:"sec-1-3",label:"",showLabel:!0,sentences:[[{text:"大畜",glossary:"g06"},"其卦福之生，",{text:"无妄",glossary:"g07"},"若遇祸之始。"]]},{id:"sec-1-4",label:"",showLabel:!0,sentences:[["升者去而不复回，萃者聚而终不去。"]]},{id:"sec-1-5",label:"",showLabel:!0,sentences:[["谦卦自尊豫怠人，震则动而艮则止。"]]},{id:"sec-1-6",label:"",showLabel:!0,sentences:[["兑主外遇祸之藏，随前坎后偷安矣。"]]},{id:"sec-1-7",label:"",showLabel:!0,sentences:[["剥体消烂复自生，蛊改前非而已矣。"]]},{id:"sec-1-8",label:"",showLabel:!0,sentences:[[{text:"明夷",glossary:"g10"},"内朗又逢伤，晋主外明并通理。"]]},{id:"sec-1-9",label:"",showLabel:!0,sentences:[["益拟茂盛损象衰，咸速恒迟涣远遁。"]]},{id:"sec-1-10",label:"",showLabel:!0,sentences:[["同人内亲睽外疏，解卦从容蹇难启。"]]},{id:"sec-1-11",label:"",showLabel:!0,sentences:[["离文美丽艮光明，遁退回身姤相遇。"]]},{id:"sec-1-12",label:"",showLabel:!0,sentences:[["大有曰众丰曰多，坎卦履险震卦起。"]]},{id:"sec-1-13",label:"",showLabel:!0,sentences:[["需不进兮讼不宁，既济一定无后虑。"]]},{id:"sec-1-13b",label:"",showLabel:!0,sentences:[["未济之卦男之终，归妹之辞归之始。"]]},{id:"sec-1-14",label:"",showLabel:!0,sentences:[["否遭大往而小来，泰卦大来而小去。"]]},{id:"sec-1-15",label:"",showLabel:!0,sentences:[["革去旧故鼎从新，小畜曰寡",{text:"噬嗑",glossary:"g18"},"食。"]]},{id:"sec-1-16",label:"",showLabel:!0,sentences:[["旅羁其外大过颠，",{text:"夬卦",glossary:"g17"},"分明曰快利。"]]},{id:"sec-1-17",label:"",showLabel:!0,sentences:[["要将字字考精详，杂卦性情",{text:"反对",glossary:"g01"},"是。"]]},{id:"sec-02",label:"占物类例",showLabel:!0,sentences:[["凡看物数，看其成卦，观其爻辞。"],["如得干，曰潜龙勿用，乃曰不可用之物；见龙在田，乃曰田中之物；或跃在渊，乃曰水中之物；亢龙有悔，乃废物也。"]]},{id:"sec-02-1",label:"",showLabel:!0,sentences:[["如得坤之直、方、大，乃曰直而方大之器物；",{text:"括囊",glossary:"g19"},"无咎，乃曰包裹之物；",{text:"黄裳",glossary:"g20"},"元吉，乃曰黄色衣服之物；其血玄黄，乃石物或逢石而破；困于",{text:"株林",glossary:"g21"},"，乃曰木物。"]]},{id:"sec-02-2",label:"",showLabel:!0,sentences:[["又言爻辞，不言物类，而不能决者，须以八卦所属之象察之。"],["又诀，体用断物之妙，生克制化之妙，于诸诀中此极为美验。"],["其所以生体者，为可食之物；克体者，为可近人之秽物。"]]},{id:"sec-02-3",label:"",showLabel:!0,sentences:[["体生者，为不成之器；体克者，为破碎损折之物；比和者，乃有用成器之物，又生体象者为贵物，克体象者为贱物，所泄为废物也。"],["又诀，凡算此数，以体卦为主，看其刚柔。"],["用卦看其有用无用。"],["体生方圆曲直，可作可用，如用生体，乃可食。"],["用变互卦，看其色与数目。"],["此互卦决其物之数目也。"]]},{id:"sec-02-4",label:"",showLabel:!0,sentences:[["如互见干、兑，决为一二之数。"],["互见艮、坤，为七八之数也。"],["但互卦重干、重艮、重坤、重坎、重离之属，皆是两件。"],["物乘旺，物数多，衰而物少。"],["离为中虚之物，或空手无物。"],["又决物之数者，如互艮卦，先天七数，后天亦不出八数之外。"]]},{id:"sec-03",label:"物数为体诀",showLabel:!0,sentences:[["凡算物数者，不但以体卦为体，凡卦之多者，皆可为体。"],["如干金多，以金为体，则多刚；坤多以土为体，多柔。"],["干卦体卦干而互又是干。"],["固曰：金为体而刚矣，便是圆健刚硬之物。"],["非金非石，此为体矣。"]]},{id:"sec-03-1",label:"",showLabel:!0,sentences:[["观物有体互变卦，并无生旺之气者，为不入五行物。"],["观物观爻，如八卦中阳爻多，乃多刚之物；阴爻多，乃多柔之物。"],["又诀，观物变在五六爻，多是能飞动之物。"]]},{id:"sec-04",label:"观物看变爻为主",showLabel:!0,sentences:[["凡观物，以变卦为主，应用之应验也。"],["如得干，初爻变为巽，金刀削过之木物。"],["二爻动，变为离，乃火中锻炼之金。"],["三爻动，变为兑，乃毁折",{text:"五金",glossary:"g26"},"之器，虽圆而破处多也。"]]},{id:"sec-05",label:"观物克应法",showLabel:!0,sentences:[["凡算物之成败，又看体卦克应如何。"],["成卦未决之际，有见圆物相遇，即断圆物。"],["见有负土者过，即断为土中之物。"],["见刚健之物，即言是刚健之物。"],["见有柔腐之物，即言是柔腐之物。"]]},{id:"sec-06",label:"观物趣时诀",showLabel:!0,sentences:[["凡算物，",{text:"趣时",glossary:"g22"},"察理，无有不验。"],["以春得震、离为花，夏得震为有声之物，秋得兑为毁折成器之物，冬得坤为无用土物也。"]]},{id:"sec-07",label:"观物用易例",showLabel:!0,sentences:[["有人以笼盛物者，算得地天泰之初变升，互见震、兑，曰此必是草木类而生土中也。"],["色青根黄，当连根之草木也。"],["盖爻辞曰：拔茅茹，以其汇。"],["乃曰：此乃干根之草木也，视之乃草木连根，新采于土中也。"]]},{id:"sec-07-1",label:"",showLabel:!0,sentences:[["互震为清色，兑为黄根也。"],["又有以",{text:"锺覆",glossary:"g23"},"物者，令占之，得火风鼎之雷风恒。"],["乃曰：此有声价气势之物，虽圆而今毁缺矣。"]]},{id:"sec-07-2",label:"",showLabel:!0,sentences:[["其色白而可用。"],["盖其辞曰：鼎玉铉，大吉。"],["互见干、兑，虽圆而毁也。"],["开视之，乃",{text:"玉绦环",glossary:"g24"},"，果破矣。"]]},{id:"sec-08",label:"万物戏验",showLabel:!0,sentences:[["凡猜手中物，干金为圆白之物。"],["其色白，其性刚，为宝货之物，有气为无价物。"]]},{id:"sec-08-1",label:"",showLabel:!0,sentences:[["坎为黑色，性柔，近水之物。"],["又艮为土中之物，瓦石之类，有气为成器之物，其色黄。"]]},{id:"sec-08-2",label:"",showLabel:!0,sentences:[["逢兑克，无气，折伤之物。"],["又巽、震为竹木，有气为有用之物，为可食之物；无气为竹木之属。"]]},{id:"sec-08-3",label:"",showLabel:!0,sentences:[["遇兑之属可食，当时之果物，色青。"],["有气柔，无气刚。"]]},{id:"sec-08-4",label:"",showLabel:!0,sentences:[["震、巽遇坎为污湿物，或有气；如无气，为烂朽之木。"]]},{id:"sec-08-5",label:"",showLabel:!0,sentences:[["离色亦，性柔，有水有木，而火焚之，必炭之类。"],["有气，为价值可货之物。"]]},{id:"sec-08-6",label:"",showLabel:!0,sentences:[["坤为土中之物，色黄而性温。"]]},{id:"sec-08-7",label:"",showLabel:!0,sentences:[["兑为毁折之物，带口。"]]},{id:"sec-08-8",label:"",showLabel:!0,sentences:[["凡占物，以春震巽、夏离、秋干兑、冬坎皆当以为可用之物，成器之物。"],["否则为无用之物。"],["值",{text:"六虚冲破",glossary:"g25"},"，则必无物而空手矣。"]]}],glossary:[{id:"g01",term:"反对",pinyin:"—",meaning:"易学术语，指卦象颠倒（上下互换）或错卦（阴阳互换）"},{id:"g02",term:"比卦",pinyin:"bǐ",meaning:"水地比，亲比·欢欣之象"},{id:"g03",term:"困卦",pinyin:"—",meaning:"泽水困，困厄·忧虑之象"},{id:"g04",term:"蒙卦",pinyin:"méng",meaning:"山水蒙，蒙昧·难明之象"},{id:"g05",term:"屯卦",pinyin:"zhūn",meaning:"水雷屯，艰难但不失，屯：难也"},{id:"g06",term:"大畜",pinyin:"—",meaning:"山天大畜，积蓄·福之生"},{id:"g07",term:"无妄",pinyin:"—",meaning:"天雷无妄，无故之灾，祸之始"},{id:"g08",term:"萃卦",pinyin:"cuì",meaning:"泽地萃，聚集·不散"},{id:"g09",term:"豫卦",pinyin:"yù",meaning:"雷地豫，怠惰·安逸"},{id:"g10",term:"明夷",pinyin:"míng yí",meaning:"地火明夷，内明外伤，夷：伤也"},{id:"g11",term:"晋卦",pinyin:"jìn",meaning:"火地晋，外明·进也"},{id:"g12",term:"涣卦",pinyin:"huàn",meaning:"风水涣，涣散·远"},{id:"g13",term:"遁卦",pinyin:"dùn",meaning:"天山遁，退避·远遁"},{id:"g14",term:"睽卦",pinyin:"kuí",meaning:"火泽睽，乖离·外疏"},{id:"g15",term:"蹇卦",pinyin:"jiǎn",meaning:"水山蹇，艰难·难以启动"},{id:"g16",term:"姤卦",pinyin:"gòu",meaning:"天风姤，相遇·邂逅"},{id:"g17",term:"夬卦",pinyin:"guài",meaning:"泽天夬，决断·快利"},{id:"g18",term:"噬嗑",pinyin:"shì hé",meaning:"火雷噬嗑，噬：咬，嗑：合，主饮食·刑狱"},{id:"g19",term:"括囊",pinyin:"kuò náng",meaning:"扎紧袋口，包裹之物"},{id:"g20",term:"黄裳",pinyin:"huáng cháng",meaning:"黄色下裳（裙），元吉"},{id:"g21",term:"株林",pinyin:"zhū lín",meaning:"树木丛林，困于株林：困于木物"},{id:"g22",term:"趣时",pinyin:"qù shí",meaning:"顺应时令，趣：趋向"},{id:"g23",term:"锺覆",pinyin:"zhōng fù",meaning:"用钟（器皿）覆盖，令人猜测其中之物"},{id:"g24",term:"玉绦环",pinyin:"tāo",meaning:"绦：丝带，玉绦环：穿有丝带的玉环"},{id:"g25",term:"六虚冲破",pinyin:"—",meaning:"六爻皆动或冲克，卦象空虚，主无物"},{id:"g26",term:"五金",pinyin:"—",meaning:"金·银·铜·铁·锡，泛指金属器物"}],"aria-label":"观物占原文"}),t[4]||(t[4]=r("",133))])}const k=e(o,[["render",h]]);export{y as __pageData,k as default};
